package com.universe.school.service; import com.universe.global.exception.*; import jakarta.mail.MessagingException; import jakarta.mail.internet.MimeMessage; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.ObjectProvider; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.mail.javamail.MimeMessageHelper; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class SchoolMailService {private final ObjectProvider<JavaMailSender> senderProvider; public void send(String to,String code){JavaMailSender sender=senderProvider.getIfAvailable(); if(sender==null)throw new BusinessException(ErrorCode.MAIL_NOT_CONFIGURED); try{MimeMessage m=sender.createMimeMessage(); MimeMessageHelper h=new MimeMessageHelper(m,false,"UTF-8");h.setTo(to);h.setSubject("UNI:VERSE 학교 이메일 인증");h.setText("학교 이메일 인증코드: "+code+"\n5분 이내에 입력해주세요.");sender.send(m);}catch(MessagingException e){throw new BusinessException(ErrorCode.MAIL_NOT_CONFIGURED);}}}
